package com.example.rokidkeyboardbridge;
import android.app.*;import android.graphics.*;import android.util.Base64;import android.widget.*;import org.json.JSONObject;
final class GeneratedImagePreview {
 interface Edit {void send(String prompt,String id);}
 static void show(Activity host,JSONObject job,Edit callback)throws Exception{String encoded=job.getString("thumbnail");if(encoded.length()>300000)throw new IllegalArgumentException("preview too large");byte[] bytes=Base64.decode(encoded,Base64.NO_WRAP);BitmapFactory.Options o=new BitmapFactory.Options();o.inJustDecodeBounds=true;BitmapFactory.decodeByteArray(bytes,0,bytes.length,o);if(o.outWidth<1||o.outHeight<1||(long)o.outWidth*o.outHeight>300000)throw new IllegalArgumentException("preview bounds");Bitmap b=BitmapFactory.decodeByteArray(bytes,0,bytes.length);ImageView image=new ImageView(host);image.setAdjustViewBounds(true);image.setScaleType(ImageView.ScaleType.FIT_CENTER);image.setImageBitmap(b);AlertDialog dialog=new LokiAlertDialogBuilder(host).setTitle("生成画像・原寸はスマホに保存").setView(image).setNegativeButton("閉じる",null).setPositiveButton("この画像を編集",(d,w)->{EditText text=new EditText(host);text.setHint("変更する内容");new LokiAlertDialogBuilder(host).setTitle("生成画像を編集").setView(text).setMessage("指示と編集元画像をGeminiへ送信します").setPositiveButton("生成",(a,v)->callback.send(text.getText().toString(),job.optString("id"))).setNegativeButton("取消",null).show();}).create();dialog.setOnDismissListener(d->{image.setImageDrawable(null);if(b!=null)b.recycle();});dialog.show();}
}
